func (this *Shell) FixActiveShell() {
	if this.display.activeShell == this && (this.style&ON_TOP) != 0 {
		var shell *Shell = nil
		if this.parent != (nil) && this.parent.impl.isVisible_() {
			shell = this.parent.impl.getShell_()
		}
		if shell == (nil) && this.IsUndecorated() {
			var shells []*Shell = this.display.GetShells()
			for i := int32(0); i < int32(len(shells)); i++ {
				if shells[i] != (nil) && shells[i].impl.isVisible_() {
					shell = shells[i]
					break
				}
			}
		}
		if shell != (nil) {
			shell.BringToTop(false)
		}
	}
}

func (this *Shell) FixShell(newShellLike ShellLike, controlLike ControlLike) {
	var newShell *Shell
	if newShellLike != nil {
		newShell = newShellLike.AsShell()
	}
	_ = newShell
	var control *Control
	if controlLike != nil {
		control = controlLike.AsControl()
	}
	_ = control
	if this == newShell {
		return
	}
	if control == this.lastActive {
		this.SetActiveControl(nil)
	}
	var toolTipText string = control.toolTipText
	if toolTipText != "" {
		control.impl.setToolTipTextShellNewString_(this, "")
		control.impl.setToolTipTextShellNewString_(newShell, toolTipText)
	}
}

